DROP TABLE IF EXISTS raw.fire_odm;

CREATE TABLE raw.fire_odm (
    start_vid BIGINT,
    end_vid   BIGINT,
    agg_cost  DOUBLE PRECISION
);


COMMENT ON TABLE raw.fire_odm IS
'Origin-destination network costs generated by pgRouting in the source book. start_vid and end_vid refer to vertices/road-network identifiers from the book''s ways table; agg_cost is the calculated network routing cost. These identifiers are not directly equivalent to FDNY station IDs or parcel IDs in this project.';